from itertools import combinations
from collections import deque

n = 11
edges = [(0, 3), (0, 4), (0, 6), (0, 8), (0, 10), (1, 2), (1, 3), (1, 4), (1, 6), (1, 8), (1, 9), (1, 10), (2, 3), (2, 7), (2, 8), (3, 4), (3, 5), (3, 6), (3, 7), (3, 8), (4, 5), (4, 7), (4, 9), (5, 8), (5, 10), (7, 9), (8, 9)]

fixed_edges = [(0,6), (1,10), (3,6), (3,8), (2,7), (0,4), (1,6), (0,8), (1,2), (5,10), (0,3)]

# Check all fixed edges are present
for e in fixed_edges:
    assert e in edges or (e[1], e[0]) in edges, f"Fixed edge {e} missing!"

print("All fixed edges present: OK")

# Check degrees
degrees = {i: 0 for i in range(n)}
for u, v in edges:
    degrees[u] += 1
    degrees[v] += 1
print("Degrees:", degrees)
assert all(d >= 3 for d in degrees.values()), "Some vertex has degree < 3"
print("All degrees >= 3: OK")

# Check max independent set
adj = {i: set() for i in range(n)}
for u, v in edges:
    adj[u].add(v)
    adj[v].add(u)

max_is = 0
for size in range(n, 0, -1):
    found = False
    for subset in combinations(range(n), size):
        is_independent = True
        for i in range(len(subset)):
            for j in range(i+1, len(subset)):
                if subset[j] in adj[subset[i]]:
                    is_independent = False
                    break
            if not is_independent:
                break
        if is_independent:
            max_is = size
            found = True
            break
    if found:
        break

print(f"Maximum independent set size: {max_is}")
assert max_is <= 4, f"MIS = {max_is} > 4"
print("MIS <= 4: OK")

# Check vertex connectivity >= 3
def is_connected(edge_set, vertices):
    if not vertices:
        return True
    adj_local = {v: set() for v in vertices}
    for u, v in edge_set:
        if u in adj_local and v in adj_local:
            adj_local[u].add(v)
            adj_local[v].add(u)
    visited = set()
    queue = deque([vertices[0]])
    visited.add(vertices[0])
    while queue:
        node = queue.popleft()
        for neighbor in adj_local[node]:
            if neighbor not in visited:
                visited.add(neighbor)
                queue.append(neighbor)
    return len(visited) == len(vertices)

for removed in combinations(range(n), 2):
    remaining = [v for v in range(n) if v not in removed]
    if not is_connected(edges, remaining):
        print(f"Connectivity fails when removing {removed}")
        break
else:
    print("Vertex connectivity >= 3: OK")

print("\nAll constraints satisfied!")
print(f"Solution edges: {sorted(edges)}")
